"""Independent battery thermal learning stages and portfolio card."""
from pathlib import Path

def publish_pages(root):
    root=Path(root)
    for name in ['battery-thermal.html','battery-thermal-cad.html','battery-thermal-stage-02.html','battery-thermal-stage-03.html','battery-thermal-stage-04.html','battery-thermal-stage-05.html','battery-thermal-stage-06.html']:
        (root/'AISolutions'/name).write_text((root/'scripts/content'/name).read_text())

def battery_thermal_card():
    return '''<article class="simulation-card filter-item" id="battery-thermal" data-category="Thermal" data-method="systems" data-analysis-company-ids="independent-work"><div class="card-copy"><p class="eyebrow">Independent work / Battery thermal modeling</p><h2>Battery thermal modeling, step by step</h2><p>Start with one cell, then build a coupled PCB and enclosure model. The latest stage compares three graphite sizes, tracking the back-cover hot spot, battery average and peak, coverage and added mass.</p><div class="pills"><span>FreeCAD</span><span>Python</span><span>SciPy</span><span>Open source</span></div><p class="study-note">Stages 01–06 available · Graphite size and battery-temperature comparison · Layered finite volumes and lumped packages · Assumed inputs · Numerically verified, not experimentally validated.</p></div><a class="analysis-research-image" href="/AISolutions/battery-thermal-stage-06.html" aria-label="Open the graphite size comparison"><img src="/assets/studies/battery-thermal/stage-06/figures/size_maps.png" alt="Back-cover and battery temperature maps for three graphite footprints" loading="lazy" width="1760" height="1440"></a><div class="card-bottom"><a class="text-link" href="/AISolutions/battery-thermal.html">Start with Stage 01 →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-02.html">Compare heat input →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-03.html">Explore PCB &amp; enclosure →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-04.html">Compare the RF cooling pad →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-05.html">Explore graphite spreading →</a><a class="text-link" href="/AISolutions/battery-thermal-stage-06.html">Compare graphite sizes →</a></div></article>'''
